usage:
package main

import (
	"context"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	err := client.Containers.Files.Content(context.TODO(), "container_id", "file_id")
	if err != nil {
		panic(err.Error())
	}
}
